// Normalise so tiny differences (extra spaces, capital letters) don't make a retry look like a new request
const email = String($json.body.customer_email ?? "").trim().toLowerCase();
const message = String($json.body.message ?? "")
  .trim()                  // remove spaces at the start and end
  .replace(/\s+/g, " ")    // collapse any run of spaces/tabs/newlines into one space
  .toLowerCase();

const requestHash = email + "|" + message;

return {
  json: {
    ...$json,
    request_hash: requestHash
  }
};

return {
  json: {
    duplicate_blocked: true,
    message: "This request was already processed, skipping to avoid duplicate action."
  }
};

const output = $json.output;

// Get the model's actual text from the response
   const text = output?.[0]?.content?.[0]?.text;
// No text at all means the OpenAI response itself is broken (an API problem, not bad model output),
// so this still fails loudly on purpose
if (!text) {
  throw new Error("Could not find SAGE's generated text in the OpenAI response.");
}

// LLMs sometimes wrap JSON in ```json fences or add a sentence before/after it.
// Keep only the part from the first "{" to the last "}".
const start = text.indexOf("{");
const end = text.lastIndexOf("}");
const jsonText = (start !== -1 && end > start) ? text.slice(start, end + 1) : text;

let data;
try {
  data = JSON.parse(jsonText);
} catch (err) {
  data = null;
}

// Valid JSON that isn't a plain object (e.g. a string or a list) is just as unusable
if (data === null || typeof data !== "object" || Array.isArray(data)) {
  return {
    json: {
      intent: null,          // Schema Validation rejects this → Validation Failed (End)
      issue_types: [],
      issue_description: null,
      customer_stated_amount: null,
      parse_error: "SAGE's output was not valid JSON",
      raw_output: text
    }
  };
}

return {
  json: data
};

function parseAmount(value) {
  if (value === null || value === undefined) return null;

  // Already a number: keep it only if it's a real, finite number
  if (typeof value === "number") return Number.isFinite(value) ? value : null;

  if (typeof value !== "string") return null;

  const text = value.toLowerCase();

  // Find the first number (commas allowed, optional decimals), plus an optional unit right after it
  const match = text.match(/(\d[\d,]*(?:\.\d+)?)\s*(crores?|cr|lakhs?|lacs?|l|k|thousand)?\b/);
  if (!match) return null;

  const base = Number(match[1].replace(/,/g, ""));
  if (!Number.isFinite(base)) return null;

  const MULTIPLIERS = {
    crore: 1e7, crores: 1e7, cr: 1e7,
    lakh: 1e5, lakhs: 1e5, lac: 1e5, lacs: 1e5, l: 1e5,
    k: 1e3, thousand: 1e3
  };

  const unit = match[2];
  const amount = unit ? base * MULTIPLIERS[unit] : base;

  // Round to 2 decimals, e.g. 1.15 * 100000 gives 114999.99999... in JS
  return Math.round(amount * 100) / 100;
}

const data = $json;

return {
  json: {
    ...data,
    customer_stated_amount: parseAmount(data.customer_stated_amount)
  }
};

const ALLOWED_INTENTS = [
  "refund_request", "cancellation_request", "delivery_issue",
  "return_request", "replacement_request", "technical_support",
  "general_question", "other", "unrelated"
];

const ALLOWED_ISSUE_TYPES = [
  "damaged_product", "missing_item", "product_malfunction",
  "connectivity_issue", "software_issue", "warranty_issue",
  "support_followup", "service_request"
];

const data = $json;
const errors = [];

// NEW: check the customer's ORIGINAL message, not SAGE's summary of it.
// The LLM can invent a description for a blank message, so this check doesn't rely on it.
const originalMessage = String($('Webhook').item.json.body.message ?? "").trim();
if (originalMessage === "") {
  errors.push("customer message is empty");
}

if (!ALLOWED_INTENTS.includes(data.intent)) {
  errors.push("intent is not a recognized value: " + data.intent);
}

if (!Array.isArray(data.issue_types) || !data.issue_types.every(type => ALLOWED_ISSUE_TYPES.includes(type))) {
  errors.push("issue_types contains an invalid value: " + JSON.stringify(data.issue_types));
}

// Money-related requests must say what's wrong
const MONEY_INTENTS = ["refund_request", "cancellation_request", "return_request", "replacement_request"];

if (MONEY_INTENTS.includes(data.intent)) {
  const hasDescription = typeof data.issue_description === "string" && data.issue_description.trim() !== "";
  const hasIssueTypes = Array.isArray(data.issue_types) && data.issue_types.length > 0;

  if (!hasDescription && !hasIssueTypes) {
    errors.push(data.intent + " has no description of the problem");
  }
}

// Number.isFinite rejects NaN, Infinity and strings
if (data.customer_stated_amount !== null && !Number.isFinite(data.customer_stated_amount)) {
  errors.push("customer_stated_amount is not a valid number: " + JSON.stringify(data.customer_stated_amount));
}

return {
  json: {
    ...data,
    validation: {
      passed: errors.length === 0,
      errors: errors
    }
  }
};

const orderData = $json;
const intent = $('Schema Validation').item.json.intent;

// Only refund/replacement-type intents involve money and need this check
const refundRelatedIntents = ['refund_request', 'replacement_request', 'return_request', 'cancellation_request'];
const isRefundRelated = refundRelatedIntents.includes(intent);

// Number() is strict: any junk makes it NaN instead of quietly reading part of it
const actualAmount = Number(orderData.amount_paid);

// A usable amount must be a real, positive number
const amountIsValid = Number.isFinite(actualAmount) && actualAmount > 0;

// An order can only be refunded once
const alreadyRefunded = isRefundRelated && orderData.status === 'refunded';

// Fail closed: an invalid amount always goes to a human
const requiresApproval = isRefundRelated && !alreadyRefunded && (!amountIsValid || actualAmount > 10000);

// NEW: Indian number formatting for display only (65000 → "65,000")
const formattedAmount = amountIsValid ? actualAmount.toLocaleString('en-IN') : String(orderData.amount_paid);

let decisionReason;
if (!isRefundRelated) {
  decisionReason = `Intent "${intent}" does not involve a refund — no approval needed.`;
} else if (alreadyRefunded) {
  decisionReason = `Order #${orderData.order_id} has already been refunded — no further refund allowed.`;
} else if (!amountIsValid) {
  decisionReason = `Order amount "${orderData.amount_paid}" is missing or invalid — human review required.`;
} else if (requiresApproval) {
  decisionReason = `Refund amount ₹${formattedAmount} exceeds ₹10,000 threshold — human approval required.`;
} else {
  decisionReason = `Refund amount ₹${formattedAmount} is within auto-approval limit.`;
}

return {
  json: {
    ...orderData,
    actual_amount: actualAmount,
    already_refunded: alreadyRefunded,
    requires_human_approval: requiresApproval,
    decision_reason: decisionReason
  }
};

