const data = $json;

return {
  json: {
    query_embedding: data.embeddings[0]
  }
};

const result = $json;
const SIMILARITY_THRESHOLD = 0.5;

const hasConfidentMatch = result.similarity >= SIMILARITY_THRESHOLD;

return {
  json: {
    policy_category: hasConfidentMatch ? result.category : null,
    policy_content: hasConfidentMatch ? result.content : null,
    policy_similarity: result.similarity,
    policy_match_confident: hasConfidentMatch
  }
};

return {
  json: {
    error_occurred: true,
    error_message: $json.error?.message || "Embedding API failed after retries",
    policy_category: null,
    policy_content: null,
    policy_similarity: 0,
    policy_match_confident: false
  }
};

const params = [
  $('Lookup Real Order').item.json.customer_id,
  $('Lookup Real Order').item.json.order_id,
  $('Schema Validation').item.json.intent,
  '{' + $('Schema Validation').item.json.issue_types.join(',') + '}',
  $('Schema Validation').item.json.issue_description,
  $('Schema Validation').item.json.customer_stated_amount,
  $('Business Rules').item.json.actual_amount,
  $('Business Rules').item.json.requires_human_approval,
  'rejected',
  $json.policy_category,     // NEW: $10
  $json.policy_similarity    // NEW: $11
];

return {
  json: { params }
};

// Must match the list in Business Rules
const refundRelatedIntents = ['refund_request', 'replacement_request', 'return_request', 'cancellation_request'];

const intent = $('Schema Validation').item.json.intent;
const alreadyRefunded = $('Business Rules').item.json.already_refunded;

// What actually happened to this case
let status;
if (!refundRelatedIntents.includes(intent)) {
  status = 'logged';             // not a refund at all (delivery issue, general question)
} else if (alreadyRefunded) {
  status = 'already_refunded';   // refund request, but the order was already refunded
} else {
  status = 'approved';           // refund went through (human-approved or under the threshold)
}

const params = [
  $('Lookup Real Order').item.json.customer_id,
  $('Lookup Real Order').item.json.order_id,
  intent,
  '{' + $('Schema Validation').item.json.issue_types.join(',') + '}',
  $('Schema Validation').item.json.issue_description,
  $('Schema Validation').item.json.customer_stated_amount,
  $('Business Rules').item.json.actual_amount,
  $('Business Rules').item.json.requires_human_approval,
  $json.policy_category,
  $json.policy_similarity,
  status                         // NEW: $11
];

return {
  json: { params }
};

