const caseId = $('Log Case (Approved)').item.json.id;
const orderId = $('Lookup Real Order').item.json.order_id;
const amount = $('Business Rules').item.json.actual_amount;

const params = [
  caseId,
  orderId,
  amount,
  "refund"
];

return {
  json: { params }
};

return {
  json: {
    validation_failed: true,
    errors: $json.validation.errors,
    message: "SAGE's extraction failed validation — stopping before further processing."
  }
};

const orderData = $json;
const intent = $('Schema Validation').item.json.intent;

if (intent !== 'delivery_issue') {
  return { json: { ...orderData, is_delivery_issue: false } };
}

const orderDate = new Date(orderData.order_date);
const today = new Date();
const daysSinceOrder = Math.floor((today - orderDate) / (1000 * 60 * 60 * 24));

const priority = daysSinceOrder > 5 ? "high" : "normal";

return {
  json: {
    ...orderData,
    is_delivery_issue: true,
    days_since_order: daysSinceOrder,
    priority: priority,
    recommended_action: priority === "high"
      ? "Escalate to shipping carrier immediately, offer replacement or refund"
      : "Monitor delivery status, follow up if not resolved within 48 hours"
  }
};

const caseId = null; // we'll link this properly if time allows; for now, tracked independently
const orderId = $('Lookup Real Order').item.json.order_id;
const daysSinceOrder = $('Delivery Business Rules').item.json.days_since_order;
const priority = $('Delivery Business Rules').item.json.priority;
const recommendedAction = $('Delivery Business Rules').item.json.recommended_action;

const params = [orderId, daysSinceOrder, priority, recommendedAction];

return { json: { params } };

const orderData = $json;
const rawClaimed = $('Schema Validation').item.json.order_id;
const actualOrderId = Number(orderData.order_id);

let claimedOrderId = null;
let orderMismatch = false;

// Only check if the customer actually mentioned an order (?? catches both null and undefined)
const claimedText = String(rawClaimed ?? "").trim();

if (claimedText !== "") {
  const digits = claimedText.match(/\d+/);   // "#2", "ORD-2", "order 2" → "2"

  if (digits) {
    claimedOrderId = Number(digits[0]);
    orderMismatch = claimedOrderId !== actualOrderId;   // now number vs number
  } else {
    // They referenced an order we can't read at all (e.g. "ORD-XXXX"): flag it for a human
    claimedOrderId = claimedText;
    orderMismatch = true;
  }
}

return {
  json: {
    ...orderData,
    order_mismatch: orderMismatch,
    claimed_order_id: claimedOrderId
  }
};

